<style>@page{size:Letter;margin:12mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#1e293b;margin:0;font-size:10px}.toolbar{padding:10px 0;border-bottom:1px solid #ddd;margin-bottom:14px}.btn{border:0;border-radius:8px;padding:9px 14px;font-weight:700;cursor:pointer}.primary{background:#6d28d9;color:#fff}.secondary{background:#e2e8f0}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #6d28d9;padding-bottom:10px}.brand{font-size:20px;font-weight:900;color:#5b21b6}.muted{color:#64748b}.score{text-align:right;font-size:27px;font-weight:900;color:#5b21b6}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:12px}.box{border:1px solid #dbe4ee;border-radius:8px;padding:8px}.section{margin-top:15px;break-inside:avoid}.section h2{font-size:13px;color:#5b21b6;border-bottom:1px solid #ddd;padding-bottom:4px;margin:0 0 7px}.scores{display:grid;grid-template-columns:repeat(5,1fr);gap:6px}.scores .box{text-align:center}.scores strong{font-size:16px}.gauge{width:112px;height:62px;margin:4px auto 0;display:block}.visual-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:10px;align-items:center}.radar{width:100%;max-width:250px;margin:auto;display:block}.legend{font-size:8.5px;color:#64748b;text-align:center}.bar{height:6px;background:#e2e8f0;border-radius:6px;margin-top:5px;overflow:hidden}.fill{height:100%;background:#0891b2}table{width:100%;border-collapse:collapse;margin-top:5px}th,td{border:1px solid #dbe4ee;padding:5px;vertical-align:top}th{background:#f1f5f9;text-align:left;font-size:9px}.item{font-weight:700}.small{font-size:9px}.footer{margin-top:18px;border-top:1px solid #ddd;padding-top:7px;color:#64748b;font-size:8.5px}.page-break{break-before:page}@media print{*{-webkit-print-color-adjust:exact;print-color-adjust:exact}.toolbar{display:none}.section{break-inside:avoid}}</style></head><body>
