 const radar=document.getElementById('print-radar');if(radar){const vals=[Number(@json($hine->cranial_nerves_score ?? 0))/15,Number(@json($hine->posture_score ?? 0))/18,Number(@json($hine->movements_score ?? 0))/6,Number(@json($hine->tone_score ?? 0))/24,Number(@json($hine->reflexes_reactions_score ?? 0))/15].map(v=>Math.max(0,Math.min(1,v)));const labels=['Pares','Postura','Mov.','Tono','Reflejos'],cx=150,cy=125,r=82,p=(i,s=1)=>{const a=(-90+i*72)*Math.PI/180;return[cx+Math.cos(a)*r*s,cy+Math.sin(a)*r*s]};[.25,.5,.75,1].forEach(s=>radar.appendChild(mk('polygon',{points:vals.map((_,i)=>p(i,s).join(',')).join(' '),fill:'none',stroke:'#cbd5e1','stroke-width':1})));vals.forEach((_,i)=>{const q=p(i),l=p(i,1.22);radar.appendChild(mk('line',{x1:cx,y1:cy,x2:q[0],y2:q[1],stroke:'#cbd5e1'}));const t=mk('text',{x:l[0],y:l[1],'text-anchor':'middle','font-size':10,'font-weight':700,fill:'#475569'});t.textContent=labels[i];radar.appendChild(t)});radar.appendChild(mk('polygon',{points:vals.map((v,i)=>p(i,v).join(',')).join(' '),fill:'#cffafe','fill-opacity':.7,stroke:'#0891b2','stroke-width':2.5}));}
